package com.ruoyi.medical.persistence;
import com.ruoyi.medical.identity.ApplicationSessionIdentity;import com.ruoyi.medical.persistence.mapper.*;import java.util.*;import javax.sql.DataSource;import org.junit.jupiter.api.Test;import org.springframework.context.annotation.AnnotationConfigApplicationContext;import org.springframework.core.env.MapPropertySource;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Real conditional wiring with named dependency doubles, not deployment acceptance. */
class FormalEvaluationNodeInputWiringTest {
 static final List<Class<?>> READ=List.of(FormalEvaluationPlanPreparationReadService.class,FormalEvaluationPlanPreparationSchema.class,AgentPublicationDependencies.class,DependencyLineage.class,SourceReadMapper.class,ArtifactRegistryMapper.class,DependencyManifestSchema.class,ResourceReadAuthority.class);
 AnnotationConfigApplicationContext context(boolean enabled,Class<?> omit)throws Exception{var c=new AnnotationConfigApplicationContext();c.getEnvironment().getPropertySources().addFirst(new MapPropertySource("test",Map.of("medical.formal-evaluation-node-input.enabled",Boolean.toString(enabled))));c.getBeanFactory().registerSingleton("access",mock(EnterpriseAccess.class));c.getBeanFactory().registerSingleton("identity",mock(ApplicationSessionIdentity.class));c.getBeanFactory().registerSingleton("db",mock(DataSource.class));var json=new PermissionSchema();c.getBeanFactory().registerSingleton("json",json);c.getBeanFactory().registerSingleton("schema",new FormalEvaluationNodeInputObjectSchema(json));for(var type:READ)if(type!=omit)c.getBeanFactory().registerSingleton(type.getSimpleName(),mock(type));c.register(FormalEvaluationNodeInputConfiguration.class,FormalEvaluationNodeInputController.class);c.refresh();return c;}
 @Test void historicalReadStartsWithoutModelBudgetOrWriteDependencies()throws Exception{try(var c=context(true,null)){assertNotNull(c.getBean(FormalEvaluationNodeInputReadService.class));assertTrue(c.getBeansOfType(FormalEvaluationNodeInputObjectService.class).isEmpty());assertTrue(c.getBeansOfType(FormalEvaluationModelPreparation.class).isEmpty());assertTrue(c.getBeansOfType(RuntimeObjectTransport.class).isEmpty());}}
 @Test void absentPrerequisitesOrDisabledFlagCannotEnablePreparation()throws Exception{try(var c=context(false,null)){assertTrue(c.getBeansOfType(FormalEvaluationNodeInputReadService.class).isEmpty());assertTrue(c.getBeansOfType(FormalEvaluationNodeInputController.class).isEmpty());}for(var type:READ)try(var c=context(true,type)){assertTrue(c.getBeansOfType(FormalEvaluationNodeInputReadService.class).isEmpty(),type.getName());assertTrue(c.getBeansOfType(FormalEvaluationNodeInputObjectService.class).isEmpty());}}
}
